SELECT rentabilidad_1.deudor AS deudor,   rentabilidad_1.rutadeventa AS rutadeventa,   SUM(rentabilidad_1.rentabilidad) AS temp(calculation_5560818164729849)(3482281234)(0),   SUM(rentabilidad_1.cf) AS temp(calculation_5560818164729849)(3669921802)(0) FROM rentabilidad_1 WHERE ((rentabilidad_1.figura = 'Preventa On Premise') AND (rentabilidad_1.sedeforaneosintec = 'Sede') AND (rentabilidad_1.zona = 'OC')) GROUP BY rentabilidad_1.deudor,   rentabilidad_1.rutadeventa;
